  private assertProfile(profileId: string, actual: string) { if (profileId !== actual) throw new IntegrationFixtureError('PROFILE_MISMATCH', 'Integration belongs to another profile.') }
  async snapshot(params: { profileId: string; projectId?: string; refresh?: boolean }): Promise<IntegrationPlatformSnapshot> {
    await this.wait()
    return {
      skills: { skills: [...this.skills.values()].filter((item) => item.profileId === params.profileId && (!params.projectId || item.projectId === params.projectId)).map((item) => clone(item.record.skill)), sources: [], diagnostics: [] },
      mcp: { servers: [...this.servers.values()].filter((item) => item.profileId === params.profileId && (!params.projectId || item.projectId === params.projectId)).map((item) => clone(item.record.server)), sources: [], diagnostics: [] }
    }
  }
